package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class KnowledgeReviewsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String id=KnowledgeDraftsAcceptance.seed(h.store),reviewer;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","KnowledgeBrowserReviewer","role","admin","password",WorkflowSupport.PASSWORD));reviewer=RecordAccess.owner(db,"KnowledgeBrowserReviewer");Service.createAccount(db,map("name","KnowledgeBrowserReader","role","reader","password",WorkflowSupport.PASSWORD));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var ownerContext=browser.newContext();var reviewerContext=browser.newContext();var readerContext=browser.newContext()){
   var page=ownerContext.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/knowledge/"+id+"/draft");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Publication and retirement review").setExact(true)).press("Enter");page.getByLabel("Reviewer",new Page.GetByLabelOptions().setExact(true)).selectOption(reviewer);page.getByLabel("Confirm review policy change").check();ServiceOutagesBrowserAcceptance.click(page,"Save review policy");try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE user_id=?",reviewer);db.connection.commit();}page.reload();assertThat(page.getByLabel("Reviewer",new Page.GetByLabelOptions().setExact(true))).hasValue(reviewer);try(var db=h.store.open()){db.update("UPDATE os_user SET active=1 WHERE user_id=?",reviewer);db.connection.commit();}page.reload();page.getByLabel("Confirm submitting this action for review").check();ServiceOutagesBrowserAcceptance.click(page,"Submit for review");assertThat(page.locator("main")).containsText("Status: pending");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record review decision"))).hasCount(0);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/knowledge-review-pending-light.png")).setFullPage(true));
   var review=reviewerContext.newPage();h.login(review,"KnowledgeBrowserReviewer");review.navigate(h.base()+"/admin/knowledge/"+id+"/review");assertThat(review.locator("main")).containsText("Unpublished work");review.getByLabel("Decision reason").fill("Reviewed independently <script>");review.getByLabel("Confirm this independent review decision").check();ServiceOutagesBrowserAcceptance.click(review,"Dark mode");review.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(review);assertEquals(false,review.evaluate("document.documentElement.scrollWidth>window.innerWidth"));review.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/knowledge-review-decision-dark.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(review,"Record review decision");assertThat(review.locator("main")).containsText("Status: approved");assertEquals(0,review.locator("main script").count());var reader=readerContext.newPage();h.login(reader,"KnowledgeBrowserReader");reader.navigate(h.base()+"/knowledge/"+id);assertThat(reader.locator("main")).containsText("Current instructions");page.reload();page.getByLabel("Confirm applying the approved action").check();ServiceOutagesBrowserAcceptance.click(page,"Apply approved action");reader.reload();assertThat(reader.locator("main")).containsText("Unpublished work");
   page.getByLabel("Requested action").selectOption("retire");page.getByLabel("Confirm submitting this action for review").check();ServiceOutagesBrowserAcceptance.click(page,"Submit for review");review.reload();review.getByLabel("Decision",new Page.GetByLabelOptions().setExact(true)).selectOption("reject");review.getByLabel("Decision reason").fill("Keep instructions available");review.getByLabel("Confirm this independent review decision").check();ServiceOutagesBrowserAcceptance.click(review,"Record review decision");page.reload();assertThat(page.locator("main")).containsText("Status: rejected");reader.reload();assertThat(reader.locator("main")).containsText("Unpublished work");page.getByLabel("Requested action").selectOption("retire");page.getByLabel("Confirm submitting this action for review").check();ServiceOutagesBrowserAcceptance.click(page,"Submit for review");review.reload();review.getByLabel("Decision reason").fill("Superseded instructions");review.getByLabel("Confirm this independent review decision").check();ServiceOutagesBrowserAcceptance.click(review,"Record review decision");page.reload();page.getByLabel("Confirm applying the approved action").check();ServiceOutagesBrowserAcceptance.click(page,"Apply approved action");assertThat(page.locator("main")).containsText("retired");reader.reload();assertThat(reader.locator("main")).containsText("not found");ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/knowledge-review-retired-dark.png")).setFullPage(true));
  }
 }
}
